const $=id=>document.getElementById(id);
let token=location.hash.slice(1) || sessionStorage.getItem('narae-token');
if(token){sessionStorage.setItem('narae-token',token);history.replaceState(null,'',location.pathname);}
let conversation=null,files=[],busy=false,activeJob=null,seen=0,modelState;
const nameMap={'narae1':'나래1','narae2':'나래2','narae3':'나래3'};
const labels={'system.status':'도구 연결 상태','skill.read':'업무 절차 확인','browser':'나래 브라우저','portal.open':'업무포털 열기','cbe.search':'교직원 검색','cbe.notes':'쪽지 조회','cbe.chats':'대화 조회','cbe.prepare':'연락 준비','hangul.inspect':'한글 문서 읽기','hangul.view':'나래한글 뷰어','hangul.create':'한글 문서 작성','hangul.edit':'한글 문서 수정','hangul.run':'한글 작업','wxs':'공문서 에디터 조회','wxs.prepare':'기안 입력 준비','wxs.save':'임시저장 준비','files.list':'작성 파일 목록'};
async function api(route,data){
  const response=await fetch('/api/'+route,{method:data===undefined?'GET':'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
  const result=await response.json();if(!result.ok)throw new Error(result.error?.message || '실행기 오류');return result.data;
}
function notice(text){$('notice').hidden=!text;$('notice').textContent=text || '';}
function setBusy(value){busy=value;$('send').disabled=value;$('cancel').hidden=!value;$('input').disabled=value;document.querySelectorAll('.model-card button,.action-card button').forEach(b=>{if(!b.dataset.used)b.disabled=value;});}
function element(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;}
function message(role,text,error=false,label){$('welcome')?.remove();const el=element('div','message '+role+(error?' error':''));el.append(element('span','message-label',label || (role==='user'?'나':'나래교무')),element('div','bubble',text));$('messages').append(el);el.scrollIntoView({block:'end'});return el;}
function execution(event){const el=element('details','execution');el.append(element('summary','',(event.type==='tool'?'실행 중 · ':'확인 · ')+(labels[event.name] || event.name)));el.append(element('pre','',JSON.stringify(event.args || event.result,null,2)));$('messages').append(el);}
function thinking(text){let el=$('thinking');if(!el){el=element('div','thinking',text);el.id='thinking';$('messages').append(el);}else el.textContent=text;el.scrollIntoView({block:'end'});}
function renderModels(state){modelState=state;$('models').replaceChildren();
  for(const m of state.models){const el=element('div','model-card'+(state.active===m.id?' active':''));const head=element('div');head.append(element('strong','',m.label),element('span','size',m.size));el.append(head,element('p','',m.note));const button=element('button','',state.loading===m.id?'불러오는 중…':state.active===m.id?'● 활성화됨':m.installed?'활성화':'모델 파일 없음');button.disabled=busy || Boolean(state.loading) || !m.installed;
    button.addEventListener('click',async()=>{setBusy(true);notice('');$('model-status').textContent=m.label+' 불러오는 중…';try{renderModels(await api('models/activate',{id:m.id}));$('activity').textContent=m.label+'에게 명령할 수 있습니다.';}catch(e){notice(e.message);}finally{setBusy(false);await status();}});el.append(button);$('models').append(el);}
  $('model-status').textContent=state.loading?(nameMap[state.loading]+' 불러오는 중…'):state.active?(nameMap[state.active]+' 실행 중 · 하나만 활성화'):'활성화할 AI를 선택하세요';
}
async function status(){const s=await api('status');renderModels(s.models);$('output-path').textContent=s.outputs;return s;}
async function conversations(){const list=await api('conversations');$('conversations').replaceChildren();for(const c of list){const button=element('button',conversation===c.id?'selected':'',c.title);button.addEventListener('click',()=>loadConversation(c.id));$('conversations').append(button);}}
async function loadConversation(id){if(busy)return;const c=await api('conversations/'+id);conversation=id;$('messages').replaceChildren();for(const m of c.messages)message(m.role,m.content,m.error,m.model?Object.values(nameMap).find(n=>m.model.includes(n)) || '나래교무':undefined);await conversations();}
function attachmentList(){$('attachments').replaceChildren();for(const f of files){const el=element('span','file-chip',f.name),remove=element('button','','×');remove.type='button';remove.addEventListener('click',()=>{files=files.filter(x=>x.path!==f.path);attachmentList();});el.append(remove);$('attachments').append(el);}}
function previewText(data){
  const p=data.preview;if(data.kind!=='cbe')return JSON.stringify(p,null,2);
  const recipients=p.recipients.map(person=>[person.name,person.department,person.position].filter(Boolean).join(' · ')).join('\n');
  return '받는 사람\n'+recipients+(p.title?'\n\n제목: '+p.title:'')+'\n\n본문\n'+p.body+(p.files.length?'\n\n첨부\n'+p.files.join('\n'):'');
}
function pending(data){if($('pending-'+data.pendingId))return;const card=element('div','action-card');card.id='pending-'+data.pendingId;card.append(element('strong','',data.kind==='cbe'?'연락 내용을 확인하세요':'공문 적용 내용을 확인하세요'),element('pre','',previewText(data)));const button=element('button','',data.kind==='cbe'?'이 내용으로 전송':'이 내용 적용');button.addEventListener('click',async()=>{button.disabled=true;button.dataset.used='1';try{const result=await api('pending/confirm',{id:data.pendingId});card.classList.add('done');card.replaceChildren(element('strong','','실행 결과를 확인했습니다'),element('pre','',JSON.stringify(result,null,2)));}catch(e){card.append(element('p','',e.message));notice('결과가 불명확하면 같은 작업을 다시 적용하지 말고 원래 기록을 확인하세요.');}});button.disabled=busy;card.append(button);$('pending').append(card);}
async function poll(id){
  while(true){const job=await api('jobs/'+id);for(const event of job.events.slice(seen)){seen=event.index+1;if(event.type==='thinking')thinking((nameMap[job.model] || '선택한 AI')+'가 업무를 확인하고 있습니다…');if(event.type==='tool' || event.type==='observation')execution(event);if(event.type==='observation' && event.result.data?.pendingId)pending(event.result.data);if(event.type==='answer'){message('assistant',event.answer,false,nameMap[job.model]);$('activity').textContent=event.status==='needs_input'?'필요한 정보를 이어서 알려주세요.':event.toolErrors?'일부 도구 오류가 있습니다. 실행 기록을 확인하세요.':'답변을 확인했습니다.';}if(event.type==='error')message('assistant',event.error.message,true);}
    if(job.status!=='running'){conversation=job.conversationId;break;}await new Promise(r=>setTimeout(r,600));
  }
  $('thinking')?.remove();activeJob=null;setBusy(false);await conversations();await status();
}
$('chat-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const text=$('input').value.trim();if(!text)return;notice('');message('user',text);$('input').value='';setBusy(true);thinking('명령을 준비하고 있습니다…');try{const job=await api('chat',{text,conversationId:conversation,files:files.map(f=>f.path)});activeJob=job.id;seen=0;files=[];attachmentList();await poll(job.id);}catch(e){notice(e.message);$('thinking')?.remove();setBusy(false);}});
$('input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('chat-form').requestSubmit();}});
$('cancel').addEventListener('click',async()=>{await api('cancel',{});$('activity').textContent='중단 요청을 보냈습니다. 실행된 동작의 확인을 기다립니다.';});
$('attach').addEventListener('click',async()=>{try{let selected;if(window.naraeDesktop)selected=await window.naraeDesktop.chooseFiles();else{const name=prompt('이 PC 파일의 절대 경로를 입력하세요.');selected=name?[name]:[];}if(selected.length){const registered=await api('files/register',{files:selected});files=[...files,...registered];attachmentList();}}catch(e){notice(e.message);}});
$('new-chat').addEventListener('click',()=>{if(busy)return;conversation=null;files=[];attachmentList();$('messages').replaceChildren();$('pending').replaceChildren();message('assistant','새 대화입니다. 어떤 업무를 도와드릴까요?');conversations();});
document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{$('input').value=button.dataset.prompt;$('input').focus();}));
$('portal-button').addEventListener('click',async()=>{try{await api('tools/call',{tool:'portal.open',args:{}});notice('브라우저를 열었습니다. 해당 창에서 직접 로그인한 뒤 명령을 이어가세요.');}catch(e){notice(e.message);}});
$('check-button').addEventListener('click',async()=>{try{const result=await api('tools/call',{tool:'system.status',args:{}});renderComponents(result.components);notice('설치 상태를 확인했습니다. 포털·CBE 로그인 여부는 해당 도구를 조회할 때 확인합니다.');}catch(e){notice(e.message);}});
function renderComponents(components={}){$('components').replaceChildren();for(const [key,title,desc,icon] of [['browser','나래 브라우저','웹 탐색 · 포털 화면','↗'],['hangul','나래 한글','HWP · HWPX 문서','▤'],['cbe','CBE CLI','교직원 검색 · 쪽지 · 대화','◌'],['portal','나래교무포털','나이스 · 에듀파인 · WXS','▦']]){const el=element('div','component'),copy=element('div');copy.append(element('strong','',title),element('span','',components[key]?.installed===false?'환경 확인 필요':desc));el.append(element('div','component-icon',icon),copy);$('components').append(el);}}
$('outputs-button').addEventListener('click',async()=>{try{const result=await api('tools/call',{tool:'files.list',args:{}});$('file-list').replaceChildren();if(!result.files.length)$('file-list').append(element('p','','아직 작성한 파일이 없습니다.'));for(const file of result.files){const row=element('div','output-row',file.name);if(/\.hwpx?$/i.test(file.name)){const view=element('button','','나래뷰어');view.addEventListener('click',async()=>{try{await api('tools/call',{tool:'hangul.view',args:{path:file.path}});}catch(e){notice(e.message);}});row.append(view);}if(window.naraeDesktop){const open=element('button','','열기 ↗');open.addEventListener('click',()=>window.naraeDesktop.openOutput(file.path));row.append(open);}row.append(element('small','',file.path));$('file-list').append(row);}$('files-dialog').showModal();}catch(e){notice(e.message);}});
$('close-files').addEventListener('click',()=>$('files-dialog').close());
try{renderComponents();await status();await conversations();}catch(e){notice(e.message);}
